-- Approved V3 catalogue, 24/11/2026. Staging only, no sale activation.
ALTER TABLE v3_retrospective_packages ADD COLUMN max_video_seconds INTEGER NOT NULL DEFAULT 60 CHECK(max_video_seconds>0);
ALTER TABLE v3_retrospective_packages ADD COLUMN max_total_video_seconds INTEGER NOT NULL DEFAULT 180 CHECK(max_total_video_seconds>0);
ALTER TABLE v3_retrospective_packages ADD COLUMN specific_terms TEXT NOT NULL DEFAULT '';
UPDATE v3_atelie_packages SET included_json=replace(included_json, ',"1 simulação conceitual digital de decoração"', ''), specific_terms=replace(specific_terms, 'Apresentação da identidade em PDF e uma simulação conceitual digital de decoração.', 'Apresentação da identidade em PDF. Não inclui simulação de decoração.'), updated_at=datetime('now')
WHERE sale_enabled=0 AND scope_approved=1;
UPDATE v3_retrospective_packages SET name='Memórias',max_photos=70,max_videos=5,price_cents=14900,points_units=200,revision_limit=1,captions_included=0,max_video_seconds=60,max_total_video_seconds=180,included_json='["Abertura personalizada","Trilha sonora","Transições animadas","Dedicatória final","Entrega Full HD"]',specific_terms='Entrega digital em Full HD. Até 70 fotos e 5 vídeos previamente recortados, até 60 segundos por vídeo e 3 minutos no conjunto contratado. Materiais organizados pela cliente e enviados exclusivamente pelo WhatsApp. Os trechos utilizados são definidos na edição. A Libri confirma recebimento completo. Prazo mínimo de 15 dias corridos após pagamento confirmado, briefing completo e recebimento dos materiais. 1 rodada(s) de revisão incluída(s); ajustes pontuais agrupados, correções de erros da Libri não consomem rodada. Excedentes, trocas de materiais após início da edição e alterações de escopo dependem de orçamento e aceite. Solicitação de ajustes em até 7 dias da prévia; sem aprovação automática por silêncio. Arquivos finais disponíveis para download por 90 dias após entrega. Materiais originais mantidos no aplicativo por 30 dias após entrega, quando aplicável; retrospectiva não usa R2 para mídia recebida. Uso de materiais com autorização do titular ou responsável; divulgação depende de autorização separada. Duração final estimada, não garantida.',scope_approved=1,updated_at=datetime('now') WHERE code='RETRO_070' AND sale_enabled=0;
